<div class="row g-4"><div class="col-xl-8"><section class="admin-card enquiry-detail"><div class="card-head"><div><span class="status status-<?=strtolower($rfq['status'])?>"><?=e(str_replace('_',' ',$rfq['status']))?></span><h2><?=e($rfq['reference'])?></h2><p>Submitted <?=e(date('d F Y \a\t h:i A',strtotime($rfq['created_at'])))?></p></div></div><div class="detail-grid"><?php foreach(['Full name'=>'full_name','Company'=>'company_name','Phone'=>'phone','WhatsApp'=>'whatsapp','Email'=>'email','Location'=>null,'Category'=>'category_name','Product'=>'product_name','Quantity'=>'quantity_requirement','Application'=>'application','Preferred contact'=>'preferred_contact_method'] as $label=>$field):?><div><span><?=e($label)?></span><strong><?=e($field?$rfq[$field]??'—':trim($rfq['city'].', '.$rfq['state'],', '))?></strong></div><?php endforeach;?></div><div class="message-box"><span>Message</span><p><?=nl2br(e($rfq['message']?:'No additional message.'))?></p></div></section></div><div class="col-xl-4"><section class="admin-card form-section sticky-form"><h2>Manage request</h2><form method="post" action="<?=e(url('admin/enquiries/'.$rfq['id'].'/status'))?>"><?=csrf_field()?><label>Status</label><select class="form-select" name="status"><?php foreach($statuses as $status):?><option value="<?=e($status)?>" <?=$rfq['status']===$status?'selected':''?>><?=e(str_replace('_',' ',$status))?></option><?php endforeach;?></select><button class="btn btn-primary w-100 mt-3">Update Status</button></form><hr><form method="post" action="<?=e(url('admin/enquiries/'.$rfq['id'].'/mark'))?>"><?=csrf_field()?><input type="hidden" name="read" value="<?=$rfq['is_read']?'0':'1'?>"><button class="btn btn-light w-100">Mark as <?=$rfq['is_read']?'Unread':'Read'?></button></form><form class="mt-3" method="post" action="<?=e(url('admin/enquiries/'.$rfq['id'].'/delete'))?>" data-confirm="Delete this quote request permanently?"><?=csrf_field()?><button class="btn btn-outline-danger w-100">Delete Request</button></form><a class="back-admin" href="<?=e(url('admin/enquiries'))?>"><i class="fa-solid fa-arrow-left"></i> Back to requests</a></section></div></div>

